contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), 1000000000000000000); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function testEthBalanceMatchesActualBalance(uint256 unused) public {
        require(address(c).balance == 0);
        uint256 reported = c.ethBalance(); if (__ESBMC_reverted()) return;
        assert(reported == address(c).balance);
    }

    receive() external payable {}
    fallback() external payable {}
}

