pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 1000000000000000000);
    }

    function _testEthBalanceMatchesActualBalance(uint256 unused) internal {
        vm.assume(address(c).balance == 0);
        uint256 reported;
        try c.ethBalance() returns (uint256 __r) { reported = __r; } catch { return; }
        assertTrue(reported == address(c).balance);
    }

    function testFuzz_testEthBalanceMatchesActualBalance(uint256 unused) public {
        _testEthBalanceMatchesActualBalance(unused);
    }

    receive() external payable {}

    fallback() external payable {}
}
